def squash(s: str) -> str:
    result = []
    i = 0
    n = len(s)

    while i < n:
        char = s[i]
        j = i + 1
        while j < n and s[j] == char:
            j += 1

        escaped = "\\" + char if "0" <= char <= "9" or char == "\\" else char
        count = j - i
        if count >= 3:
            result.append(str(count) + escaped)
        else:
            result.append(escaped * count)

        i = j

    return "".join(result)
